"""FastAPI app generated by sp2react. Run: uvicorn app.main:app --reload"""
from __future__ import annotations

import os
from pathlib import Path

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from . import custom
from .api import router
from .store import Specs, SqliteRepo


def create_app() -> FastAPI:
    app = FastAPI(title="Converted SharePoint screens", version="1.0")
    app.state.specs = Specs()
    source = os.environ.get("DATA_SOURCE", "__DEFAULT_SOURCE__")
    if source == "database":
        from .sql_repo import SqlRepo          # your existing tables, through mapping.json
        app.state.repo = SqlRepo(app.state.specs)
    elif source == "sharepoint":
        from .sp_repo import SharePointRepo
        app.state.repo = SharePointRepo(app.state.specs)
    else:
        app.state.repo = SqliteRepo(app.state.specs)
    app.include_router(router)
    for name, mod in custom.load().items():
        if hasattr(mod, "router"):
            app.include_router(mod.router, prefix="/api/custom")
    origins = [o for o in os.environ.get("CORS_ORIGINS", "http://localhost:5173").split(",") if o]
    app.add_middleware(CORSMiddleware, allow_origins=origins, allow_methods=["*"], allow_headers=["*"], allow_credentials=True)

    dist = Path(os.environ.get("FRONTEND_DIST", Path(__file__).resolve().parents[2] / "frontend" / "dist"))
    if dist.exists():
        app.mount("/assets", StaticFiles(directory=dist / "assets"), name="assets")

        @app.get("/{path:path}", include_in_schema=False)
        def spa(path: str):
            f = dist / path
            return FileResponse(f if f.is_file() else dist / "index.html")
    return app


app = create_app()
